?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Solicitudes de cuenta empresarial | Administración</title><link rel="stylesheet" href="../assets/style.css?v=admin-navigation-20261015"><link rel="stylesheet" href="../assets/admin.css?v=admin-workflow-20261015-3"><?php require __DIR__.'/_theme.php'; ?></head><body class="portal-admin"><main class="wrap admin-page destination-admin"><a class="brand" href="index.php"><span>Explorando<b>Lugares</b></span></a><p><a href="index.php">← Volver al panel</a></p><h1>Solicitudes de cuenta de negocio</h1><p>Consulta las solicitudes y sus evidencias. Una cuenta asociada no certifica titularidad. La asociación y la publicación son acciones diferentes.</p><?php require __DIR__.'/_navigation.php'; ?><?php if($error):?><p class="notice" role="alert"><?=esc($error)?></p><?php endif ?><?php if($dbError):?><p class="notice" role="alert"><?=esc($dbError)?> <a href="base-datos.php">Ver estado de la base de datos</a>.</p><?php endif ?><?php if(($_GET['actualizada']??'')==='1'):?><p class="notice" role="status">Se actualizó el estado de la solicitud y su asociación, si fue aprobada.</p><?php endif ?><section class="destination-admin-list"><h2>Solicitudes recibidas <small>(<?=count($applications)?>)</small></h2><?php if(!$applications&&!$dbError):?><p>Aún no hay solicitudes empresariales.</p><?php elseif($applications):?><div class="destination-admin-table"><table><thead><tr><th>Negocio solicitado</th><th>Cuenta</th><th>Solicitud</th><th>Estado</th><th>Documentos y decisión</th></tr></thead><tbody><?php foreach($applications as $item):$evidence=$service->applicationEvidence((int)$item['id']);?><tr><td><strong><?=esc($item['business_name'])?><br><a href="solicitud-detalle.php?type=account&amp;id=<?=esc($item['id'])?>" target="_blank" rel="noopener">Revisar solicitud ↗</a></strong><br><?=esc($item['destination_name'])?> · <?=esc($item['category_label'])?><br><small><?=esc($item['business_id']?'Negocio #'.$item['business_id']:'Se creará privado al aprobar')?></small></td><td><?=esc($item['account_name'])?><br><?=esc($item['email'])?><br><?=esc($item['contact_phone']?:'Sin teléfono adicional')?></td><td><?=esc($item['application_type']==='claim_existing'?'Asociar un negocio existente':'Incorporar un negocio nuevo')?><br><?=esc(['owner'=>'Propietario/a','legal_representative'=>'Representante legal','authorized_administrator'=>'Administrador/a autorizado/a','authorized_representative'=>'Representante autorizado/a'][$item['relationship_code']]??'Relación por revisar')?><br><?=esc($item['message']?:'—')?><?php require __DIR__.'/_application-details.php'; ?></td><td><?=esc(['pending'=>'Pendiente','in_review'=>'En revisión','not_approved'=>'No aprobada','approved'=>'Aprobada y asociada'][$item['status']]??$item['status'])?><br><small><?=esc($item['created_at'])?></small></td><td><?php if($evidence):?><ul class="application-evidence-list"><?php foreach($evidence as $document):?><li><label><input type="checkbox" name="verified_evidence[]" value="<?=esc($document['id'])?>" form="review-application-<?=esc($item['id'])?>" <?=!empty($document['verified_at'])?'checked disabled':''?>> Revisé <?=esc(['identity_document'=>'identidad','business_registration'=>'registro del negocio','authority_document'=>'autorización legal'][$document['evidence_type']]??'documento')?> · <a href="representacion-evidencia.php?id=<?=esc($document['id'])?>" target="_blank" rel="noopener"><?=esc($document['original_name'])?></a></label></li><?php endforeach ?></ul><?php else:?><p class="notice">No hay documentos cargados. No se puede aprobar.</p><?php endif ?><?php if(in_array($item['status'],['pending','in_review'],true)):?><form method="post" class="claim-review-form" id="review-application-<?=esc($item['id'])?>"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="review"><input type="hidden" name="application_id" value="<?=esc($item['id'])?>"><?php $isDispute=(json_decode($item['business_details_json']??'{}',true)['claim_review_kind']??'')==='disputed_existing';if($isDispute):?><p class="notice">Disputa: el responsable actual conserva su acceso hasta resolverla. Aprobar con la confirmación siguiente revoca sus asociaciones actuales y asigna esta cuenta.</p><label class="admin-checkbox-field"><input type="checkbox" name="manual_resolution" value="1"><span>Confirmo que concilié la representación con las partes y documento la decisión en la nota interna (mínimo 30 caracteres).</span></label><?php endif;?><label>Nota interna <small>Explica cómo comprobaste que esta persona puede representar el negocio.</small><input name="admin_note" maxlength="1000" placeholder="Validé identidad y registro del negocio con…"></label><div class="claim-review-actions"><button class="pill light compact" name="status" value="in_review">En revisión</button><button class="pill compact" name="status" value="approved">Aprobar y asociar</button><button class="pill danger compact" name="status" value="not_approved">No aprobar</button></div></form><?php elseif($item['status']==='approved'&&!empty($item['business_id'])):?><a href="negocios.php?id=<?=esc($item['business_id'])?>">Completar negocio</a><br><a href="suscripciones.php?id=<?=esc($item['business_id'])?>">Elegir suscripción</a><?php else:?>Solicitud cerrada<?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section></main></body></html>
